BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('HBSE-115-2-038','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題法律層面為選項D。民法第1065條規定非婚生子女經生父認領者，視為婚生子女，其經生父撫育者，視為認領；非婚生子女與其生母之關係，視為婚生子女，無須認領。第1069條之1規定非婚生子女經認領者，關於未成年子女權利義務之行使或負擔，準用第1055條等規定。非婚生子女未經認領前，與生父尚無法律上之親子關係，不生父母共同行使親權之問題，選項D錯誤；其餘選項屬生理、心理、社會層面之一般敘述。第1065條自 1930-12-26 制定後未修正，第1069條之1自 1996-09-25 增訂後未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=B0000001'),('SP106-1-11','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考各項社會保險之辦理方式。全民健康保險法第7條規定以衛生福利部中央健康保險署為保險人，勞工保險條例第5條規定設勞工保險局為保險人，公教人員保險法第5條規定由考試院會同行政院指定之承保機關辦理。學生團體保險部分，考試時國民教育法第5條之1（2016-06-01 版本）規定國民小學及國民中學應辦理學生團體保險，其辦理方式等辦法由各該主管教育行政機關定之；現行國民教育法第43條規定學校應辦理學生團體保險並另以法律定之，高級中等以下學校學生及教保服務機構幼兒團體保險條例（2020-08-01 施行）第5條規定主管機關依政府採購法以招標方式擇定保險公司或與公營保險公司締結行政契約，第10條規定保險費由主管機關補助三分之一，第11條規定低收入戶等學生全額補助。學生團體保險由保險公司承保、政府部分補助（選項C）之性質未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0070078'),('SP109-1-11','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考社會福利民營化相關法令。促進民間參與公共建設法第3條將社會及勞工福利設施列為公共建設；政府採購法第2條所稱採購包括勞務之委任或僱傭，政府委託民間辦理服務適用該法；推動社會福利民營化實施要點為行政規則。「行政法」為法學領域之統稱，並非特定法令，故選項B錯誤。促進民間參與公共建設法第3條於 2022-12-21 修正，現行條文第1項第5款仍列社會及勞工福利設施；政府採購法第2條自 1998-05-27 制定後未修正。本題答案不受上開法令修正影響。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=A0030057'),('SP109-1-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考停止社會救助之事由。社會救助法第9條規定受社會救助者提供不實之資料、隱匿或拒絕提供主管機關所要求之資料，或以詐欺或其他不正當方法取得社會救助者，主管機關應停止其社會救助（選項B、C）；第15條第4項規定不願接受就業服務措施，或接受後不願工作者，不予扶助（選項D）。受扶助者收入與資產減少並非停止救助之事由，選項A錯誤。第9條自 2010-12-29 修正後、第15條自 2015-12-30 修正後均未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP109-2-14','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考育嬰留職停薪津貼之財源。就業保險法第10條規定本保險之給付包括育嬰留職停薪津貼；第19條之2規定育嬰留職停薪津貼以被保險人平均月投保薪資百分之六十計算，按月發給。育嬰留職停薪津貼由就業保險（社會保險）支出（選項B）。第10條自 2009-04-22 修正後未再修正；第19條之2於 2022-01-12 修正（刪除父母同為被保險人應分別請領之限制等），津貼仍由就業保險給付。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021'),('SP109-2-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考職業災害保險之制度特性。考試時勞工保險條例第15條第1款規定受僱勞工等被保險人之職業災害保險費全部由投保單位負擔（職業工會、漁會會員則由被保險人與中央政府分擔），第13條第4項規定行業別災害費率對一定規模以上之投保單位採實績費率。勞工職業災害保險及保護法自 2022-05-01 施行，依第107條，勞工保險條例第13條第3項至第6項、第15條第1款至第4款等職業災害保險規定不再適用，改依該法第19條（受僱勞工等被保險人之保險費全部由投保單位負擔）及第16條（實績費率）。職業災害保險費並非由勞工與雇主共同分擔，選項A錯誤之情形未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050031'),('SP109-2-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考個人儲金制。勞工退休金條例第6條規定雇主應按月提繳退休金，儲存於勞保局設立之勞工退休金個人專戶；第23條規定月退休金及一次退休金均依勞工個人退休金專戶之本金及累積收益計算，勞工退休金制度屬個人儲金制（選項C）。第6條自 2004-06-30 制定後未修正，第23條最近一次修正為 2019-05-15，均早於考試日。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030020'),('SP110-1-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考財稅福利之特別扣除額。考試時所得稅法第17條（2021-01-20 修正公布）第1項第2款第3目設有儲蓄投資特別扣除、身心障礙特別扣除及幼兒學前特別扣除（選項B、C、D），並無女性身分特別扣除額，選項A為答案。第17條其後於 2024-01-03、2025-12-26、2026-09-11 修正（如幼兒學前特別扣除改為六歲以下並提高額度），現行條文仍有上開三項特別扣除，亦未設女性身分特別扣除額。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340003'),('SP110-2-19','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考就業安定基金之用途。就業服務法第55條第1項規定就業安定費作為加強辦理有關促進國民就業、提升勞工福祉及處理有關外國人聘僱管理事務之用。考試時就業安定基金收支保管及運用辦法第5條（2021-05-03 版本）規定基金用途包括辦理加強實施職業訓練及就業資訊等事項（選項A）、辦理失業輔助及失業保險規劃事項（選項B）、辦理外國人聘僱管理事項（選項C），勞工權益基金則用於勞工訴訟之法律扶助等，並無提供家庭暴力受害者訴訟之法律服務，官方答案選項D。現行條文第5條（2024-03-11、2026-01-02 修正）改列「失業輔助事項」，已無「失業保險規劃」；選項D仍非基金用途，但選項B依現行條文亦不完全相符，本題答案以考試時條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0090007'),('SP115-1-13','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-02-07。本題法規部分為選項D。勞工退休金條例第6條規定雇主應按月提繳退休金，儲存於勞保局設立之勞工退休金個人專戶；第14條規定雇主提繳之退休金不得低於勞工每月工資百分之六；第23條規定月退休金及一次退休金均依個人退休金專戶之本金及累積收益計算，勞退新制為確定提撥制，選項D正確；選項C（隨收隨付制通常搭配確定提撥制）為年金財務理論之錯誤敘述，不涉法規修正。第6條自 2004-06-30 制定後未修正，第14條、第23條最近一次修正為 2019-05-15，均早於考試日。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030020'),('SW-114-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-07-26。本題官方一律給分。選項所涉現行規定：中華民國刑法第319條之3處罰未經他人同意散布性影像（2023-02-08 增訂）；跟蹤騷擾防制法第3條將以電子通訊、網際網路等方法監視、觀察、跟蹤或知悉特定人行蹤列為跟蹤騷擾行為，家庭暴力防治法第2條第5款之跟蹤亦包括以電子通訊方法掌控他人行蹤；家庭暴力防治法第14條、第61條（2023-12-06 修正）就禁止散布被害人性影像等定有保護令，跟蹤騷擾防制法第5條、第12條亦有保護令之規定。上開條文於考試日後均未修正，本題給分方式不受影響。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>11 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>11 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz) IS DISTINCT FROM '478ba06020b78720c13a1f4bf58e6bb1' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz AND q.legal_status=b.status AND q.legal_note=b.note AND q.legal_source_url=b.url)<>11 THEN RAISE EXCEPTION 'postimage count'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_10, count(*) FILTER (WHERE q.legal_status='changed') changed_1, count(*) total_11 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
